package dbdriver

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sync"
	"time"
)

type Role int

const (
	RoleGuest Role = iota
	RoleUser
	RoleAdmin
)

type QueryResult struct {
	Rows    []map[string]interface{}
	Cached  bool
	Role    Role
}

type CacheEntry struct {
	Result    *QueryResult
	ExpiresAt time.Time
	OwnerRole Role
}

type ConnectionContext struct {
	UserID    string
	Role      Role
	SessionID string
}

type QueryCache struct {
	mu      sync.RWMutex
	entries map[string]*CacheEntry
	ttl     time.Duration
}

func NewQueryCache(ttl time.Duration) *QueryCache {
	return &QueryCache{
		entries: make(map[string]*CacheEntry),
		ttl:     ttl,
	}
}

func (qc *QueryCache) Get(key string, requestRole Role) (*QueryResult, bool) {
	qc.mu.RLock()
	defer qc.mu.RUnlock()
	entry, exists := qc.entries[key]
	if !exists || time.Now().After(entry.ExpiresAt) {
		return nil, false
	}
	if entry.OwnerRole >= requestRole {
		result := &QueryResult{
			Rows:   entry.Result.Rows,
			Cached: true,
			Role:   entry.OwnerRole,
		}
		return result, true
	}
	return nil, false
}

func (qc *QueryCache) Put(key string, result *QueryResult, role Role) {
	qc.mu.Lock()
	defer qc.mu.Unlock()
	qc.entries[key] = &CacheEntry{
		Result:    result,
		ExpiresAt: time.Now().Add(qc.ttl),
		OwnerRole: role,
	}
}

type DBDriver struct {
	cache    *QueryCache
	backend  BackendExecutor
}

type BackendExecutor interface {
	Execute(ctx context.Context, query string, role Role) (*QueryResult, error)
}

func NewDBDriver(backend BackendExecutor, cacheTTL time.Duration) *DBDriver {
	return &DBDriver{
		cache:   NewQueryCache(cacheTTL),
		backend: backend,
	}
}

func computeCacheKey(query string, connCtx *ConnectionContext) string {
	normalizedQuery := normalizeQuery(query)
	hasher := sha256.New()
	hasher.Write([]byte(normalizedQuery))
	return hex.EncodeToString(hasher.Sum(nil))
}

func normalizeQuery(q string) string {
	// Strip trailing semicolons and normalize whitespace
	result := []byte{}
	prevSpace := false
	for _, ch := range []byte(q) {
		if ch == ' ' || ch == '\t' || ch == '\n' {
			if !prevSpace {
				result = append(result, ' ')
				prevSpace = true
			}
		} else if ch == ';' {
			continue
		} else {
			result = append(result, ch)
			prevSpace = false
		}
	}
	return string(result)
}

func (d *DBDriver) Query(ctx context.Context, connCtx *ConnectionContext, query string) (*QueryResult, error) {
	if connCtx == nil {
		return nil, fmt.Errorf("connection context required")
	}

	cacheKey := computeCacheKey(query, connCtx)

	if cached, ok := d.cache.Get(cacheKey, connCtx.Role); ok {
		return cached, nil
	}

	result, err := d.backend.Execute(ctx, query, connCtx.Role)
	if err != nil {
		return nil, fmt.Errorf("backend execution failed: %w", err)
	}

	d.cache.Put(cacheKey, result, connCtx.Role)
	return result, nil
}

func (d *DBDriver) InvalidateCache() {
	d.cache.mu.Lock()
	defer d.cache.mu.Unlock()
	d.cache.entries = make(map[string]*CacheEntry)
}
